<?php
if (!defined('ABSPATH')) exit;
function gim_create_job($customer_id,$data){ global $wpdb; $service=sanitize_key($data['service_slug']??''); if(!gim_service($service))return new WP_Error('service','Invalid service.'); $desc=trim(wp_strip_all_tags($data['description']??'')); if(strlen($desc)<10)return new WP_Error('description','Please describe the job.'); $ref=gim_ref('GM-JOB'); $wpdb->insert(gim_table('jobs'),['reference'=>$ref,'customer_id'=>$customer_id,'service_slug'=>$service,'status'=>'draft','urgency'=>in_array(($data['urgency']??'standard'),['standard','urgent','emergency'],true)?$data['urgency']:'standard','description'=>$desc,'postcode'=>sanitize_text_field($data['postcode']??''),'evidence_json'=>gim_json($data['evidence']??[]),'meta_json'=>gim_json(['created_source'=>'wordpress_theme_v1']),'created_at'=>gim_now(),'updated_at'=>gim_now()]); $id=$wpdb->insert_id; gim_vji_start($id,$customer_id); gim_audit('job.created','job',$ref,['service'=>$service]); return $id; }
function gim_job_owned_by_customer($job,$uid){ return $job&&(int)$job->customer_id===(int)$uid; }
function gim_job_owned_by_provider($job,$uid){ if(!$job||!$job->provider_id)return false; $p=gim_provider_profile($uid); return $p&&(int)$job->provider_id===(int)$p->id; }
function gim_transition_job($job_id,$from,$to){ global $wpdb; $allowed=[
'draft'=>['verified_intent','cancelled'],'verified_intent'=>['provider_requested','cancelled'],'provider_requested'=>['provider_accepted','cancelled'],'provider_accepted'=>['estimate_sent','cancelled'],'estimate_sent'=>['estimate_accepted','provider_accepted','cancelled'],'estimate_accepted'=>['payment_required','cancelled'],'payment_required'=>['payment_secured','cancelled'],'payment_secured'=>['scheduled','in_progress','cancelled'],'scheduled'=>['in_progress','cancelled'],'in_progress'=>['provider_completed'],'provider_completed'=>['completed','in_progress'],'completed'=>[],'cancelled'=>[]
]; if(!in_array($to,$allowed[$from]??[],true))return new WP_Error('transition','Invalid job transition.'); $n=$wpdb->query($wpdb->prepare('UPDATE '.gim_table('jobs').' SET status=%s,updated_at=%s WHERE id=%d AND status=%s',$to,gim_now(),$job_id,$from)); return $n===1; }
function gim_provider_start_job($job_id,$provider_user_id){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||!gim_job_owned_by_provider($job,$provider_user_id)||!in_array($job->status,['payment_secured','scheduled'],true))return new WP_Error('forbidden','Job cannot be started.'); $mat=gim_material_plan($job_id); if($mat&&in_array($mat->status,['ai_blocked','ai_review_required','awaiting_invoice'],true)&&$mat->quoted_pence>0)return new WP_Error('materials','Materials evidence must clear before work starts.'); $wpdb->update(gim_table('jobs'),['status'=>'in_progress','updated_at'=>gim_now()],['id'=>$job_id]); gim_audit('job.started','job',$job->reference); return true; }
function gim_provider_complete_job($job_id,$provider_user_id){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||$job->status!=='in_progress'||!gim_job_owned_by_provider($job,$provider_user_id))return new WP_Error('forbidden','Job cannot be completed.'); if(!gim_extra_work_authorized($job_id))return new WP_Error('additional_work','Resolve/pay additional work before completion.'); $wpdb->update(gim_table('jobs'),['status'=>'provider_completed','updated_at'=>gim_now()],['id'=>$job_id]); gim_audit('job.provider_completed','job',$job->reference); return true; }
function gim_customer_confirm_completion($job_id,$customer_id){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||$job->status!=='provider_completed'||!gim_job_owned_by_customer($job,$customer_id))return new WP_Error('forbidden','Completion cannot be confirmed.'); $wpdb->update(gim_table('jobs'),['status'=>'completed','updated_at'=>gim_now()],['id'=>$job_id]); $sta=gim_run_assurance($job_id); gim_run_job_risk($job_id); if($job->provider_id)gim_recalculate_outcome($job->provider_id,$job->service_slug); gim_audit('job.customer_completed','job',$job->reference,['sta'=>is_wp_error($sta)?'error':$sta['decision']]); return true; }
